m3 = AlgebraIO.readAlgebraFile("resources/algebras/m3.ua")
bp2 = BigProductAlgebra(c2, 2)
bp3 = BigProductAlgebra(c3, 2)
bp_lat = BigProductAlgebra(lat2, 2)
bp_prod = BigProductAlgebra([c2, c3])
bp_m3 = BigProductAlgebra(m3, 1)
